Tool response:
Tool: check_invoice_duplicate
Description: Detect if an invoice with identical SCAC, invoice number, and amount exists 
for the same carrier within the last 90 days. Returns DUPLICATE_DETECTED 
with original audit timestamp and shipment ID if found.
Parameters:
    {
      "type": "object",
      "properties": {
        "carrier_scac": {
          "type": "string",
          "description": "SCAC code of the carrier (e.g., TRLK)",
          "title": "Carrier Scac"
        },
        "invoice_number": {
          "type": "string",
          "description": "Invoice number to check for duplicates (e.g., TLK-88442)",
          "title": "Invoice Number"
        },
        "amount": {
          "type": "number",
          "description": "Invoice amount to check for duplicates ($1,847.33)",
          "title": "Amount"
        }
      },
      "required": [
        "carrier_scac",
        "invoice_number",
        "amount"
      ]
    }
